14	/// The Insertion Modal — a 3-tab bottom sheet (Texto/Áudio/Foto) opened
15	/// from the Home/Chat "+" control (`placeholder_screens.dart`). Texto,
16	/// Áudio and Foto are all functional as of spec-3-3 (Boundaries).
17	class InsertionModal extends StatelessWidget {
18	  const InsertionModal({
19	    required this.cubit,
20	    required this.audioCubit,
21	    required this.photoCubit,
22	    super.key,
23	  });
24	
25	  final TextEntryCubit cubit;
26	  final AudioEntryCubit audioCubit;
27	  final PhotoEntryCubit photoCubit;
28	
29	  /// Presents the modal exactly as the Boundaries dictate:
30	  /// `showModalBottomSheet(isScrollControlled: true, barrierColor:
31	  /// colorScrimHeavy)`, `radiusLg` top corners + `elevation2` (drawn by
32	  /// this widget's own `Container`, not Material's `elevation` double —
33	  /// same convention `ConfirmationDialog`'s card already uses), and a
34	  /// `durationSheetUp` entrance that collapses to zero under Reduce
35	  /// Motion (`MediaQuery.disableAnimations`).
36	  ///
37	  /// [cubit]/[audioCubit]/[photoCubit] are all fresh, `get_it`-factory-
38	  /// scoped instances — one trio per "+" tap (Boundaries: "Modal open
39	  /// resets") — closed here once the sheet is gone, regardless of how it
40	  /// closed (Salvar success, "x", swipe-down, or barrier dismiss) — the
41	  /// caller never has to remember to do this itself.
42	  static Future<void> show(
43	    BuildContext context, {
44	    required TextEntryCubit cubit,
45	    required AudioEntryCubit audioCubit,
46	    required PhotoEntryCubit photoCubit,
47	  }) async {
48	    final reduceMotion = MediaQuery.of(context).disableAnimations;
49	    final controller =
50	        BottomSheet.createAnimationController(Navigator.of(context))
51	          ..duration = reduceMotion
52	              ? Duration.zero
53	              : DesignTokens.durationSheetUp
54	          // Boundaries only names the entrance, but Reduce Motion should
55	          // collapse the exit the same way — otherwise dismissing the
56	          // sheet would still animate for anyone who asked for no motion.
57	          ..reverseDuration = reduceMotion ? Duration.zero : null;
58	    try {
59	      await showModalBottomSheet<void>(
60	        context: context,
61	        isScrollControlled: true,
62	        barrierColor: DesignTokens.colorScrimHeavy,
63	        backgroundColor: Colors.transparent,
64	        elevation: 0,
65	        transitionAnimationController: controller,
66	        builder: (_) => InsertionModal(
67	          cubit: cubit,
68	          audioCubit: audioCubit,
69	          photoCubit: photoCubit,
70	        ),
71	      );
72	    } finally {
73	      // `showModalBottomSheet`'s own Future completes as soon as the
74	      // route is popped — *before* the exit (`reverse()`) animation the
75	      // framework drives on this same controller actually finishes.
76	      // Disposing immediately would cancel that animation's ticker
77	      // mid-flight, permanently freezing the sheet on screen (its
78	      // `AnimatedBuilder` keeps rendering the controller's last value,
79	      // and the route itself never reaches `AnimationStatus.dismissed`
80	      // to be removed from the `Overlay`). Documented behavior
81	      // (`BottomSheet.transitionAnimationController`'s own doc: "the
82	      // caller is responsible for disposing it when the controller is
83	      // no longer needed") — waiting for `dismissed` first is that
84	      // "no longer needed" point.
85	      if (!controller.isDismissed) {
86	        final animationDone = Completer<void>();
87	        void onStatusChange(AnimationStatus status) {
88	          if (status == AnimationStatus.dismissed) {
89	            animationDone.complete();
90	          }
91	        }
92	
93	        controller.addStatusListener(onStatusChange);
94	        await animationDone.future;
95	        controller.removeStatusListener(onStatusChange);
96	      }
97	      controller.dispose();
98	      // Review finding: each of the three cubits' cancel+close pair is
99	      // isolated in its own try/finally — without this, an exception
100	      // from an earlier step (e.g. `audioCubit.cancel()`) would skip
101	      // every later cleanup step entirely, leaking whichever cubit never
102	      // got to run its own `cancel()`/`close()`.
103	      try {
104	        await cubit.close();
105	      } finally {
106	        try {
107	          // Review finding: dismissing the whole modal while recording/
108	          // processing (the "x" button, swipe-down, or barrier tap — as
109	          // opposed to switching to another tab, which already went
110	          // through this same `cancel()`) never stopped the native
111	          // recording session; `close()` alone only cancels the
112	          // elapsed-seconds timer, not the recorder itself.
113	          // `discardPreserved: true` — unlike a tab switch, there's no
114	          // "switch back later" to preserve a transcribed/failed
115	          // recording for, so its temp file must be cleaned up here too
116	          // (Review finding) rather than leaking on disk forever once
117	          // `close()` below makes the cubit unreachable.
118	          await audioCubit.cancel(discardPreserved: true);
119	        } finally {
120	          try {
121	            await audioCubit.close();
122	          } finally {
123	            try {
124	              // Review finding: every `image_picker` pick writes a real
125	              // OS temp file — the comment this replaced incorrectly
126	              // claimed Foto "never creates a temp file of its own".
127	              // Same `discardPreserved: true` rationale as Áudio's own
128	              // call above: there's no "switch back later" once the
129	              // whole modal is closing, so a preserved
130	              // `PhotoRecognized`/`PhotoError`'s picked file must be
131	              // cleaned up here too rather than leaking on disk forever.
132	              await photoCubit.cancel(discardPreserved: true);
133	            } finally {
134	              await photoCubit.close();
135	            }
136	          }
137	        }
138	      }
139	    }
140	  }
141	
142	  @override
143	  Widget build(BuildContext context) {
144	    return MultiBlocProvider(
145	      providers: [
146	        BlocProvider.value(value: cubit),
147	        BlocProvider.value(value: audioCubit),
148	        BlocProvider.value(value: photoCubit),
149	      ],
150	      child: const _InsertionModalBody(),
151	    );
152	  }
153	}
154	
155	/// Coarse `AudioCaptureState` discriminator used only to decide whether a
156	/// given emission is a genuine transition worth announcing — e.g.
157	/// [AudioRecording]'s own per-second timer tick re-emits the same kind
158	/// repeatedly and must never re-announce "Gravando áudio" every second.
159	enum _AudioAnnounceKind {
160	  idle,
161	  recording,
162	  processing,
163	  transcribed,
164	  saving,
165	  saved,
166	  error,
167	}
168	
169	_AudioAnnounceKind _audioAnnounceKindOf(AudioCaptureState state) =>
170	    switch (state) {
171	      AudioIdle() => _AudioAnnounceKind.idle,
172	      AudioRecording() => _AudioAnnounceKind.recording,
173	      AudioProcessing() => _AudioAnnounceKind.processing,
174	      AudioTranscribed(saving: true) => _AudioAnnounceKind.saving,
175	      AudioTranscribed() => _AudioAnnounceKind.transcribed,
176	      AudioSaved() => _AudioAnnounceKind.saved,
177	      AudioError() => _AudioAnnounceKind.error,
178	    };
179	
180	/// Same "only announce a genuine transition" role as [_AudioAnnounceKind],
181	/// for `PhotoEntryCubit`.
182	enum _PhotoAnnounceKind { idle, processing, recognized, saving, saved, error }
183	
184	_PhotoAnnounceKind _photoAnnounceKindOf(PhotoCaptureState state) =>
185	    switch (state) {
186	      PhotoIdle() => _PhotoAnnounceKind.idle,
187	      PhotoProcessing() => _PhotoAnnounceKind.processing,
188	      PhotoRecognized(saving: true) => _PhotoAnnounceKind.saving,
189	      PhotoRecognized() => _PhotoAnnounceKind.recognized,
190	      PhotoSaved() => _PhotoAnnounceKind.saved,
191	      PhotoError() => _PhotoAnnounceKind.error,
192	    };
193	
194	class _InsertionModalBody extends StatefulWidget {
195	  const _InsertionModalBody();
196	
197	  @override
198	  State<_InsertionModalBody> createState() => _InsertionModalBodyState();
199	}
200	
201	class _InsertionModalBodyState extends State<_InsertionModalBody> {
202	  final _textController = TextEditingController();
203	
204	  /// The Áudio tab's own text field controller — lifted up here rather
205	  /// than owned by `_AudioTab` itself so it survives `_AudioTab` being
206	  /// rebuilt on every `AudioCaptureState` change without losing cursor
207	  /// position/focus, same rationale as [_textController] living here
208	  /// instead of inside `_TextoTab`.
209	  final _audioTextController = TextEditingController();
210	
211	  /// The Foto tab's own text field controller — same "lifted up" rationale
212	  /// as [_audioTextController].
213	  final _photoTextController = TextEditingController();
214	
215	  /// The last `AudioTranscribed.path` this controller's text was synced
216	  /// from — only a *new* transcription (a different/first path) resets
217	  /// the controller's text; the user's own edits via `onChanged` never
218	  /// get clobbered by an unrelated rebuild.
219	  String? _lastSyncedAudioPath;
220	
221	  /// Same role as [_lastSyncedAudioPath], for `PhotoRecognized.path` — a
222	  /// *new* `PhotoRecognized` for a path not yet synced (the initial OCR
223	  /// success, or a retried OCR landing after an error that never
224	  /// synced) overwrites the controller; the user's own edits (which
225	  /// re-emit the same path) never do.
226	  String? _lastSyncedPhotoPath;
227	
228	  /// Tracks the previously-seen `activeTab` so the listener can tell a
229	  /// genuine tab switch apart from the many other `TextEntryIdle`
230	  /// emissions a keystroke produces (`updateText` also emits `Idle`) —
231	  /// initialized from the cubit's own current state so the very first
232	  /// comparison (before any emission the listener sees) is still correct.
233	  late CaptureTab _lastAnnouncedTab;
234	
235	  /// Same "only announce a genuine transition" guard as [_lastAnnouncedTab],
236	  /// for `AudioEntryCubit` (see [_audioAnnounceKindOf]).
237	  late _AudioAnnounceKind _lastAudioAnnouncedKind;
238	
239	  /// Same role as [_lastAudioAnnouncedKind], for `PhotoEntryCubit` (see
240	  /// [_photoAnnounceKindOf]).
241	  late _PhotoAnnounceKind _lastPhotoAnnouncedKind;
242	
243	  @override
244	  void initState() {
245	    super.initState();
246	    _lastAnnouncedTab = context.read<TextEntryCubit>().state.activeTab;
247	    _lastAudioAnnouncedKind = _audioAnnounceKindOf(
248	      context.read<AudioEntryCubit>().state,
249	    );
250	    _lastPhotoAnnouncedKind = _photoAnnounceKindOf(
251	      context.read<PhotoEntryCubit>().state,
252	    );
253	  }
254	
255	  @override
256	  void dispose() {
257	    _textController.dispose();
258	    _audioTextController.dispose();
259	    _photoTextController.dispose();
260	    super.dispose();
261	  }
262	
263	  // Labels for the 3 tabs, shared between the announcement below and
264	  // `_TabBar`'s own rendering (`_TabBar._tabs`) — kept here too since
265	  // `selectTab`'s announcement needs the label for whichever tab the
266	  // user just switched *to*, not the cubit's own (enum-only) state.
267	  static const _tabLabels = {
268	    CaptureTab.texto: 'Texto',
269	    CaptureTab.audio: 'Áudio',
270	    CaptureTab.foto: 'Foto',
271	  };
272	
273	  // Mirrors `account_settings_screen.dart`'s own `_announce` — VoiceOver
274	  // (this app is iOS-only) doesn't reliably treat a live-region subtree
275	  // update as an announcement on its own, so every state change this
276	  // story introduces — saving, success, failure, and a tab switch — is
277	  // spoken explicitly here instead (Acceptance Criteria: "no
278	  // color/animation alone").
279	  Future<void> _announce(String message) async {
280	    if (!mounted) {
281	      return;
282	    }
283	    await SemanticsService.sendAnnouncement(
284	      View.of(context),
285	      message,
286	      TextDirection.ltr,
287	    );
288	  }
289	
290	  void _onTextEntryStateChange(BuildContext context, TextEntryState state) {
291	    // Review finding: a tab switch (re-emitted as `TextEntryIdle`,
292	    // same as every keystroke) previously went unannounced —
293	    // detected here by comparing against the last tab seen, so a
294	    // plain keystroke (same `activeTab`) never re-triggers it.
295	    if (state.activeTab != _lastAnnouncedTab) {
296	      final previousTab = _lastAnnouncedTab;
297	      _lastAnnouncedTab = state.activeTab;
298	      _announce('Aba ${_tabLabels[state.activeTab]} selecionada');
299	      // spec-3-2's Code Map: tab-switch detection also drives
300	      // `AudioEntryCubit.startRecording()`/`.cancel()` — entering Áudio
301	      // starts recording immediately (Acceptance Criteria), leaving it
302	      // stops/releases the recorder (I/O matrix: "Leave tab
303	      // mid-recording"), never the full Story 3.4 cancel choreography.
304	      final audioCubit = context.read<AudioEntryCubit>();
305	      if (state.activeTab == CaptureTab.audio) {
306	        unawaited(audioCubit.startRecording());
307	      } else if (previousTab == CaptureTab.audio) {
308	        unawaited(audioCubit.cancel());
309	      }
310	      // spec-3-3's Code Map: leaving Foto mid-pick/mid-OCR discards the
311	      // in-flight picker/OCR call (I/O matrix: "Leave tab mid-pick/OCR")
312	      // — unlike Áudio, entering Foto never starts anything on its own
313	      // (picking only ever starts from an explicit Câmera/Galeria tap).
314	      if (previousTab == CaptureTab.foto) {
315	        unawaited(context.read<PhotoEntryCubit>().cancel());
316	      }
317	    }
318	    switch (state) {
319	      case TextEntrySaved():
320	        // I/O matrix: "success closes the modal". Review finding:
321	        // wait for the announcement to actually be sent before
322	        // popping — previously fired-and-forgot in the same tick,
323	        // risking the announcement being cut off by the dismiss
324	        // transition.
325	        unawaited(
326	          _announce('Registro salvo').then((_) {
327	            if (context.mounted) {
328	              Navigator.of(context).pop();
329	            }
330	          }),
331	        );
332	      case TextEntrySaving():
333	        _announce('Salvando registro');
334	      case TextEntryError():
335	        _announce(state.message);
336	      case TextEntryIdle():
337	        break;
338	    }
339	  }
340	
341	  void _onAudioStateChange(BuildContext context, AudioCaptureState state) {
342	    if (state is AudioTranscribed && state.path != _lastSyncedAudioPath) {
343	      _lastSyncedAudioPath = state.path;
344	      _audioTextController.text = state.text;
345	    }
346	    final kind = _audioAnnounceKindOf(state);
347	    if (kind == _lastAudioAnnouncedKind) {
348	      return;
349	    }
350	    _lastAudioAnnouncedKind = kind;
351	    switch (state) {
352	      case AudioRecording():
353	        _announce('Gravando áudio');
354	      case AudioProcessing():
355	        _announce('Transcrevendo áudio');
356	      case AudioTranscribed(saving: true):
357	        _announce('Salvando registro');
358	      case AudioTranscribed():
359	        _announce('Transcrição concluída. Revise o texto antes de salvar.');
360	      case AudioError(message: final message):
361	        _announce(message);
362	      case AudioSaved():
363	        // Same "wait for the announcement" rationale as
364	        // `TextEntrySaved` above.
365	        unawaited(
366	          _announce('Registro salvo').then((_) {
367	            if (context.mounted) {
368	              Navigator.of(context).pop();
369	            }
370	          }),
371	        );
372	      case AudioIdle():
373	        // Review finding: the one `AudioCaptureState` transition
374	        // previously never announced — reachable today only via
375	        // `cancel()` resetting from `AudioRecording` (a tab switch away
376	        // mid-recording), which happened to already be covered by the
377	        // separate tab-switch announcement above, masking the gap.
378	        _announce('Gravação cancelada');
379	    }
380	  }
381	
382	  void _onPhotoStateChange(BuildContext context, PhotoCaptureState state) {
383	    if (state is PhotoRecognized && state.path != _lastSyncedPhotoPath) {
384	      _lastSyncedPhotoPath = state.path;
385	      _photoTextController.text = state.text;
386	    }
387	    final kind = _photoAnnounceKindOf(state);
388	    if (kind == _lastPhotoAnnouncedKind) {
389	      return;
390	    }
391	    _lastPhotoAnnouncedKind = kind;
392	    switch (state) {
393	      case PhotoProcessing():
394	        _announce('Reconhecendo texto da foto');
395	      case PhotoRecognized(saving: true):
396	        _announce('Salvando registro');
397	      case PhotoRecognized():
398	        _announce('Texto reconhecido. Revise o texto antes de salvar.');
399	      case PhotoError(message: final message):
400	        _announce(message);
401	      case PhotoSaved():
402	        // Same "wait for the announcement" rationale as
403	        // `TextEntrySaved`/`AudioSaved` above.
404	        unawaited(
405	          _announce('Registro salvo').then((_) {
406	            if (context.mounted) {
407	              Navigator.of(context).pop();
408	            }
409	          }),
410	        );
411	      case PhotoIdle():
412	        // Reachable via `cancel()` resetting from `PhotoProcessing` (a
413	        // tab switch away mid-pick/mid-OCR), same rationale as
414	        // `AudioIdle`'s own "Gravação cancelada" above.
415	        _announce('Captura de foto cancelada');
416	    }
417	  }
418	
419	  @override
420	  Widget build(BuildContext context) {
421	    return BlocListener<PhotoEntryCubit, PhotoCaptureState>(
422	      listener: _onPhotoStateChange,
423	      child: BlocListener<AudioEntryCubit, AudioCaptureState>(
424	        listener: _onAudioStateChange,
425	        // Review finding: `isSaving` below previously only read
426	        // `TextEntryCubit`'s state, so the tab bar/"x" close button
427	        // stayed tappable while an *audio* save was in flight
428	        // (`AudioTranscribed.saving == true`) — the same race Story
429	        // 3.1's own review fixed for the Texto tab, just unguarded on
430	        // the Áudio side. Wrapping in this `BlocBuilder` makes the whole
431	        // subtree rebuild on an `AudioEntryCubit` state change too, not
432	        // only a `TextEntryCubit` one. Same rationale — spec-3-3 —
433	        // extends this to `PhotoEntryCubit`'s own saving flag via the
434	        // nested `BlocBuilder` below.
435	        child: BlocBuilder<AudioEntryCubit, AudioCaptureState>(
436	          builder: (context, audioState) {
437	            final isAudioSaving =
438	                audioState is AudioTranscribed && audioState.saving;
439	            return BlocBuilder<PhotoEntryCubit, PhotoCaptureState>(
440	              builder: (context, photoState) {
441	                final isPhotoSaving =
442	                    photoState is PhotoRecognized && photoState.saving;
443	                return BlocConsumer<TextEntryCubit, TextEntryState>(
444	                  listener: _onTextEntryStateChange,
445	                  builder: (context, state) {
446	                    final isSaving =
447	                        state is TextEntrySaving ||
448	                        isAudioSaving ||
449	                        isPhotoSaving;
450	                    return Container(
451	                      padding: DesignTokens.screenPadding,
452	                      decoration: const BoxDecoration(
453	                        color: DesignTokens.colorSurfaceElevated,
454	                        borderRadius: BorderRadius.vertical(
455	                          top: Radius.circular(DesignTokens.radiusLg),
456	                        ),
457	                        boxShadow: DesignTokens.elevation2,
458	                      ),
459	                      child: Padding(
460	                        // Keeps the Texto field clear of the on-screen
461	                        // keyboard — the sheet is
462	                        // `isScrollControlled: true`, so it already
463	                        // grows to fit; this is the standard companion
464	                        // fix for the keyboard inset itself.
465	                        padding: EdgeInsets.only(
466	                          bottom: MediaQuery.of(context).viewInsets.bottom,
467	                        ),
468	                        child: SafeArea(
469	                          top: false,
470	                          child: Column(
471	                            mainAxisSize: MainAxisSize.min,
472	                            crossAxisAlignment: CrossAxisAlignment.stretch,
473	                            children: [
474	                              Row(
475	                                crossAxisAlignment: CrossAxisAlignment.center,
476	                                children: [
477	                                  Expanded(
478	                                    child: _TabBar(
479	                                      activeTab: state.activeTab,
480	                                      isSaving: isSaving,
481	                                    ),
482	                                  ),
483	                                  const SizedBox(width: DesignTokens.spacingSm),
484	                                  _CloseButton(isSaving: isSaving),
485	                                ],
486	                              ),
487	                              const SizedBox(height: DesignTokens.spacingMd),
488	                              switch (state.activeTab) {
489	                                CaptureTab.texto => _TextoTab(
490	                                  controller: _textController,
491	                                  state: state,
492	                                ),
493	                                CaptureTab.audio => _AudioTab(
494	                                  controller: _audioTextController,
495	                                ),
496	                                CaptureTab.foto => _FotoTab(
497	                                  controller: _photoTextController,
498	                                ),
499	                              },
500	                            ],
501	                          ),
502	                        ),
503	                      ),
504	                    );
505	                  },
506	                );
507	              },
508	            );
509	          },
510	        ),
511	      ),
512	    );
513	  }
514	}
515	
516	class _TabBar extends StatelessWidget {
517	  const _TabBar({required this.activeTab, required this.isSaving});
518	
519	  final CaptureTab activeTab;
520	
521	  /// Review finding: a save already in flight must disable the tab bar —
522	  /// without this, switching tabs mid-save let that stale `save()` call's
523	  /// eventual `TextEntrySaved`/`TextEntryError` land against a tab/text
524	  /// the user has since left (popping the modal unexpectedly, or showing
525	  /// an error nobody is looking at). `TextEntryCubit.selectTab` also
526	  /// guards against this independently — this is the UI-level half of
527	  /// that same fix.
528	  final bool isSaving;
529	
530	  static const _tabs = [
531	    (CaptureTab.texto, 'Texto'),
532	    (CaptureTab.audio, 'Áudio'),
533	    (CaptureTab.foto, 'Foto'),
534	  ];
535	
536	  @override
537	  Widget build(BuildContext context) {
538	    return Row(
539	      children: [
540	        for (var i = 0; i < _tabs.length; i++) ...[
541	          Expanded(
542	            child: _TabButton(
543	              tab: _tabs[i].$1,
544	              label: _tabs[i].$2,
545	              isActive: _tabs[i].$1 == activeTab,
546	              isSaving: isSaving,
547	            ),
548	          ),
549	          if (i < _tabs.length - 1)
550	            const SizedBox(width: DesignTokens.spacingSm),
551	        ],
552	      ],
553	    );
554	  }
555	}
556	
557	class _TabButton extends StatelessWidget {
558	  const _TabButton({
559	    required this.tab,
560	    required this.label,
561	    required this.isActive,
562	    required this.isSaving,
563	  });
564	
565	  final CaptureTab tab;
566	  final String label;
567	  final bool isActive;
568	  final bool isSaving;
569	
570	  @override
571	  Widget build(BuildContext context) {
572	    return Semantics(
573	      button: true,
574	      selected: isActive,
575	      label: 'Aba $label',
576	      // Review finding: without this, VoiceOver can also pick up the
577	      // inner `Text(label)`'s own implicit semantics as a separate node,
578	      // announcing the tab name twice back-to-back.
579	      excludeSemantics: true,
580	      child: Material(
581	        color: isActive ? DesignTokens.colorPrimary : Colors.transparent,
582	        borderRadius: const BorderRadius.all(
583	          Radius.circular(DesignTokens.radiusSm),
584	        ),
585	        child: InkWell(
586	          borderRadius: const BorderRadius.all(
587	            Radius.circular(DesignTokens.radiusSm),
588	          ),
589	          // Review finding: `null` while a save is in flight, same
590	          // "disabled `onTap` can never start a second, overlapping call"
591	          // convention `account_settings_screen.dart`'s `Switch` already
592	          // uses.
593	          onTap: isSaving
