41	  const AudioProcessing({required this.path, required this.durationSeconds});
42	
43	  final String path;
44	  final int durationSeconds;
45	}
46	
47	/// Transcription succeeded (even to an empty string) — [text] is editable
48	/// before Salvar (Acceptance Criteria), mirrored into this state by
49	/// `AudioEntryCubit.updateText` the same way `TextEntryCubit.updateText`
50	/// mirrors the Texto field. [saving] is this story's `TextEntrySaving`
51	/// equivalent folded into one state instead of a separate sibling class —
52	/// both [path]/[durationSeconds] (needed for the eventual `create()` call)
53	/// stay fixed across a save attempt, so there's nothing a sibling state
54	/// would add that a boolean field doesn't already cover just as clearly.
55	class AudioTranscribed extends AudioCaptureState {
56	  const AudioTranscribed({
57	    required this.path,
58	    required this.durationSeconds,
59	    required this.text,
60	    required this.saving,
61	  });
62	
63	  final String path;
64	  final int durationSeconds;
65	  final String text;
66	  final bool saving;
67	
68	  AudioTranscribed copyWith({String? text, bool? saving}) => AudioTranscribed(
69	    path: path,
70	    durationSeconds: durationSeconds,
71	    text: text ?? this.text,
72	    saving: saving ?? this.saving,
73	  );
74	}
