158	  /// started a brand-new recording over it. Only [AudioIdle] (fresh) or
159	  /// an [AudioError] with no file (nothing to discard) actually start.
160	  Future<void> startRecording() async {
161	    final current = state;
162	    final canStart =
163	        current is AudioIdle ||
164	        (current is AudioError && current.path == null);
165	    if (!canStart) {
166	      return;
167	    }
168	    final generation = ++_generation;
169	    bool hasPermission;
170	    try {
171	      hasPermission = await _micRecorder.hasPermission();
172	    } catch (_) {
173	      // Review finding: a thrown `PlatformException` (native-side error)
174	      // must never escape uncaught — surfaces through the same
175	      // error/retry path as a plain permission denial.
176	      if (isClosed || generation != _generation) {
177	        return;
178	      }
179	      emit(
180	        const AudioError(
181	          path: null,
182	          durationSeconds: null,
183	          message: 'Não foi possível acessar o microfone.',
184	        ),
185	      );
186	      return;
187	    }
188	    if (isClosed || generation != _generation) {
189	      return;
190	    }
191	    if (!hasPermission) {
192	      emit(
193	        const AudioError(
194	          path: null,
195	          durationSeconds: null,
196	          message:
197	              'Permissão de microfone negada. Toque em "Tentar novamente" '
198	              'para permitir o acesso.',
199	        ),
200	      );
201	      return;
202	    }
203	    try {
204	      await _micRecorder.start();
205	    } catch (_) {
206	      // Review finding: same rationale as the `hasPermission()` catch
207	      // above — a native-side start failure must surface through the
208	      // normal error/retry path instead of escaping uncaught.
209	      if (isClosed || generation != _generation) {
210	        // Review finding: the shared `_micRecorder` singleton may already
211	        // belong to a newer, currently-active generation by the time this
212	        // stale catch fires — never release it from here, only from the
213	        // generation that's still actually live, or this would silently
214	        // kill a different, active recording with no error surfaced.
215	        return;
216	      }
217	      // Also releases the native recorder best-effort (Review finding): a
218	      // partial/failed `start()` may still have left a session open.
219	      unawaited(_safeCancelRecorder());
220	      emit(
221	        const AudioError(
222	          path: null,
223	          durationSeconds: null,
224	          message: 'Não foi possível iniciar a gravação.',
225	        ),
226	      );
227	      return;
228	    }
229	    if (isClosed || generation != _generation) {
230	      // Review finding: `cancel()` bumped `_generation` (the user already
231	      // left the Áudio tab) while `start()` was in flight — stop/discard
232	      // the session we just started instead of leaving a live, unobserved
233	      // recording running.
234	      unawaited(_safeCancelRecorder());
235	      return;
236	    }
237	    _startElapsedTimer();
238	    emit(const AudioRecording(elapsedSeconds: 0));
239	  }
240	
241	  void _startElapsedTimer() {
242	    _elapsedTimer?.cancel();
243	    var elapsed = 0;
244	    _elapsedTimer = Timer.periodic(const Duration(seconds: 1), (_) {
245	      elapsed++;
246	      if (state is AudioRecording) {
247	        emit(AudioRecording(elapsedSeconds: elapsed));
248	      }
249	    });
250	  }
