361	  /// "Tentar novamente" — re-requests permission when no file was ever
362	  /// recorded, or re-transcribes the same preserved file otherwise (I/O
363	  /// matrix: never re-records, never auto-retries on its own). A no-op
364	  /// outside [AudioError], or for a save failure (non-null [AudioError.
365	  /// text]) — that case's own retry is just tapping Salvar again, handled
366	  /// by [save] directly, not this method.
367	  Future<void> retry() async {
368	    final current = state;
369	    if (current is! AudioError || current.text != null) {
370	      return;
371	    }
372	    final path = current.path;
373	    final durationSeconds = current.durationSeconds;
374	    if (path == null || durationSeconds == null) {
375	      await startRecording();
376	      return;
377	    }
378	    emit(AudioProcessing(path: path, durationSeconds: durationSeconds));
379	    await _transcribe(path, durationSeconds);
380	  }
381	
382	  /// Mirrors the Texto field's own `updateText` — keeps the transcribed
383	  /// text editable before Salvar (Acceptance Criteria). Ignored while a
384	  /// save is already in flight, same rationale as `TextEntryCubit.
385	  /// updateText`.
386	  void updateText(String text) {
387	    final current = state;
388	    if (current is AudioTranscribed && !current.saving) {
389	      emit(current.copyWith(text: text));
390	    } else if (current is AudioError && current.text != null) {
391	      // Review finding: a save failure (`AudioError` with non-null
392	      // `text`) renders the same editable field as `AudioTranscribed`
393	      // (`_AudioErrorView`'s non-retry branch) — without this branch,
394	      // typing there updated the `TextField`'s own controller visually
395	      // but never the cubit's record of the text, so a retried `save()`
396	      // would silently resend the stale pre-failure text.
397	      emit(
398	        AudioError(
399	          path: current.path,
400	          durationSeconds: current.durationSeconds,
401	          message: current.message,
402	          text: text,
403	        ),
404	      );
405	    }
406	  }
407	
408	  /// Called when the Áudio tab loses focus mid-recording/mid-processing
409	  /// (`InsertionModal`'s tab-switch listener) — the I/O matrix's "Leave
410	  /// tab mid-recording" row: stops/releases the recorder, no `create()`
411	  /// ever fires. A no-op for every other state when [discardPreserved] is
412	  /// `false` (the default) — in particular [AudioTranscribed]/[AudioError],
413	  /// where the Never clause's trivial scope (resource safety only, not
414	  /// full Story 3.4 cancel-safety) means a tab switch must preserve the
415	  /// result rather than discard it.
416	  ///
417	  /// [discardPreserved] — Review finding: `InsertionModal.show()`'s
418	  /// `finally` also calls this (before `close()`) when the *whole modal*
419	  /// is dismissed (✕/swipe-down/barrier tap), not just the tab. In that
420	  /// case there's no "switch back to the tab later" to preserve for —
421	  /// the cubit is about to be closed — so a preserved [AudioTranscribed]
422	  /// or file-carrying [AudioError]'s temp file would otherwise never be
423	  /// cleaned up and leak on disk forever. Pass `true` only from that
424	  /// call site.
425	  Future<void> cancel({bool discardPreserved = false}) async {
426	    // Bumped unconditionally — including when the state below doesn't
427	    // match either branch — so an in-flight `startRecording()`/
428	    // `stopRecording()` continuation still sees the mismatch and aborts
429	    // itself (Review finding: previously only invalidated a flow already
430	    // visible in `state`, missing the window while those methods were
431	    // still awaiting).
432	    _generation++;
433	    // Review finding: without this, a hung `_micRecorder.stop()` call
434	    // (one that never resolves) left `_stopping` stuck `true` forever —
435	    // `stopRecording()`'s own guard made it a permanent no-op for the
436	    // rest of this cubit's life. The `_generation` bump above already
437	    // makes that stale continuation's eventual result a no-op, so
438	    // resetting this eagerly is always safe, mirroring `PhotoEntryCubit.
439	    // cancel()`'s own `_picking = false` reset.
440	    _stopping = false;
441	    final current = state;
442	    if (current is AudioRecording) {
443	      _elapsedTimer?.cancel();
444	      await _safeCancelRecorder();
445	      if (isClosed) {
446	        return;
447	      }
448	      emit(const AudioIdle());
449	    } else if (current is AudioProcessing) {
450	      // The recorder itself is already stopped by the time this state is
451	      // reached (`stopRecording` stops it before emitting `AudioProcessing`)
452	      // — only resetting the cubit's own state is left, so the pending
453	      // `_transcribe` continuation's own `state is! AudioProcessing` guard
454	      // (above) drops its result instead of resurrecting this flow. Review
455	      // finding: the already-recorded file is abandoned for good at this
456	      // point (nothing will ever retry it), so it must be deleted here —
457	      // the other orphan-file case `_micRecorder.cancel()` above already
458	      // handles on its own.
459	      unawaited(_deleteRecordingFile(current.path));
460	      emit(const AudioIdle());
461	    } else if (discardPreserved) {
462	      final path = switch (current) {
463	        AudioTranscribed(path: final p) => p,
464	        AudioError(path: final p) => p,
465	        _ => null,
466	      };
467	      if (path != null) {
468	        unawaited(_deleteRecordingFile(path));
469	      }
470	    }
471	  }
472	
473	  /// Best-effort `_micRecorder.cancel()` — a thrown `PlatformException`
474	  /// here (Review finding) must never escape uncaught, since both call
475	  /// sites (above, and [startRecording]'s own abandon-on-generation-
476	  /// mismatch branch) call this fire-and-forget.
477	  Future<void> _safeCancelRecorder() async {
478	    try {
479	      await _micRecorder.cancel();
480	    } catch (_) {
481	      // Best-effort — nothing in the UI depends on this succeeding.
482	    }
483	  }
484	
485	  /// I/O matrix's "Happy path"/"Save fails" rows: fires `POST /entries`
486	  /// with `source: audio` and `mediaDurationSeconds` for the current
487	  /// transcribed text. Mirrors `TextEntryCubit.save()`'s `isClosed`/
488	  /// no-double-submit guards exactly (Boundaries).
489	  ///
490	  /// Review finding: also callable from an [AudioError] save failure
491	  /// (non-null [AudioError.text]) — `_AudioErrorView`'s non-retry branch
492	  /// re-renders the editable field and calls this same method for its
493	  /// "Salvar" button, but the original guard only matched
494	  /// [AudioTranscribed], making a retry after any save failure a
495	  /// permanent no-op.
496	  Future<void> save() async {
497	    final current = state;
498	    final String path;
499	    final int durationSeconds;
500	    final String text;
501	    if (current is AudioTranscribed && !current.saving) {
502	      path = current.path;
503	      durationSeconds = current.durationSeconds;
504	      text = current.text.trim();
505	    } else if (current is AudioError &&
506	        current.text != null &&
507	        current.path != null &&
508	        current.durationSeconds != null) {
509	      path = current.path!;
510	      durationSeconds = current.durationSeconds!;
511	      text = current.text!.trim();
512	    } else {
513	      return;
514	    }
515	    if (text.isEmpty) {
516	      return;
517	    }
518	    emit(
519	      AudioTranscribed(
520	        path: path,
521	        durationSeconds: durationSeconds,
522	        text: text,
523	        saving: true,
524	      ),
525	    );
526	    final result = await _repository.create(
527	      content: text,
528	      source: EntrySource.audio,
529	      mediaDurationSeconds: durationSeconds,
530	    );
531	    // Mirrors `TextEntryCubit.save()`'s own `isClosed` guard — this
532	    // cubit's `close()` can race the awaited call above (e.g. the modal's
533	    // barrier is dismissed mid-save).
534	    if (isClosed) {
535	      return;
536	    }
537	    result.match(
538	      (failure) => emit(
539	        AudioError(
540	          path: path,
541	          durationSeconds: durationSeconds,
542	          message: failure.message,
543	          text: text,
544	        ),
545	      ),
546	      (_) {
547	        // Review finding: the recorded temp file was never deleted after
548	        // a successful save — fire-and-forget, a deletion failure must
549	        // never block the modal from closing.
550	        unawaited(_deleteRecordingFile(path));
551	        emit(const AudioSaved());
552	      },
553	    );
554	  }
555	
556	  /// Best-effort cleanup for a temp recording file this cubit is done
557	  /// with (saved successfully, or abandoned for good by [cancel] mid-
558	  /// processing) — deletion failures are swallowed since nothing in the
559	  /// UI depends on this succeeding (Review finding: previously never
560	  /// called at all, leaking a `.wav` file per recording indefinitely).
561	  Future<void> _deleteRecordingFile(String path) async {
562	    try {
563	      await File(path).delete();
564	    } catch (_) {
565	      // Best-effort — a missing/already-deleted file, or a transient
566	      // disk error, is never worth surfacing to the user.
567	    }
568	  }
569	
570	  @override
571	  Future<void> close() {
572	    _elapsedTimer?.cancel();
573	    return super.close();
574	  }
575	}
