19	/// Only the transport boundary is faked (`HttpClientAdapter`), same
20	/// convention as `capture_flow_e2e_test.dart`'s/`audio_entry_flow_e2e_test.
21	/// dart`'s own adapter.
22	class _FakeHttpClientAdapter implements HttpClientAdapter {
23	  final List<RequestOptions> requests = [];
24	  final List<({int statusCode, Map<String, dynamic> body})> _queue = [];
25	
26	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
27	    _queue.add((statusCode: statusCode, body: body));
28	  }
29	
30	  @override
31	  Future<ResponseBody> fetch(
32	    RequestOptions options,
33	    Stream<Uint8List>? requestStream,
34	    Future<void>? cancelFuture,
35	  ) async {
36	    requests.add(options);
37	    if (_queue.isEmpty) {
38	      throw StateError(
39	        'No queued response for ${options.method} ${options.path}',
40	      );
41	    }
42	    final next = _queue.removeAt(0);
43	    return ResponseBody.fromString(
44	      jsonEncode(next.body),
45	      next.statusCode,
46	      headers: {
47	        Headers.contentTypeHeader: [Headers.jsonContentType],
48	      },
49	    );
50	  }
51	
52	  @override
53	  void close({bool force = false}) {}
54	}
