133	        .setMockMethodCallHandler(secureStorageChannel, handleSecureStorageCall);
134	    fakePathProvider = FakePathProviderPlatform();
135	    PathProviderPlatform.instance = fakePathProvider;
136	
137	    await resetCoreDependencies();
138	    await setupCoreDependencies();
139	
140	    // Swap only the transport boundary on the real, DI-resolved Dio
141	    // instance — both real interceptors (header + retry) stay attached.
142	    adapter = _FakeHttpClientAdapter();
143	    sl<Dio>().httpClientAdapter = adapter;
144	
145	    // Both `media-ocr` and `entries-create` are bearer-required
146	    // operations — seed a user access token through the real
