151	    // A real file on disk — `PhotoEntryCubit` deletes it once it's done
152	    // with it (success or abandonment), so the tests below can assert
153	    // that cleanup genuinely happened (or didn't, on a save failure).
154	    photoBytes = Uint8List.fromList([0xFF, 0xD8, 0xFF, 0xE0, 0x00, 0x01]);
155	    photoFile = File(
