335	        'code': 'VALIDATION_ERROR',
336	        'message': 'Conteúdo inválido.',
337	        'retryable': false,
338	      });
339	
340	      final cubit = sl<PhotoEntryCubit>();
341	      addTearDown(cubit.close);
342	
343	      await cubit.pickFromCamera();
344	      await cubit.save();
